import { readFileSync, writeFileSync } from 'node:fs';

const p = '/workspace/probe/corpus/gen_scalars-quoted.mjs';
let s = readFileSync(p, 'utf8');

// raw code point -> JS-escape spelling to put in the generator source
const map = [
  [0x0001, '\\u0001'],
  [0x007f, '\\u007f'],
  [0x0085, '\\u0085'],
  [0x2028, '\\u2028'],
  [0xfeff, '\\uFEFF'],
  [0x0000, '\\u0000'],
];
for (const [cp, esc] of map) {
  s = s.split(String.fromCodePoint(cp)).join(esc);
}
writeFileSync(p, s);

const bad = [...s]
  .map((c) => c.codePointAt(0))
  .filter((n) => (n < 32 && n !== 10) || n === 127 || n === 0x85 || n === 0x2028 || n === 0xfeff);
console.log('remaining raw control/special chars in source:', bad);

import { readFileSync, readdirSync } from 'node:fs';
import { execFileSync } from 'node:child_process';

const DIR = '/workspace/probe/corpus/scalars-quoted';
const EXE = '/workspace/dataset/test14_executable';
const files = readdirSync(DIR).sort();
let ok = 0, err = 0;
const show = (s) => JSON.stringify(s);

for (const f of files) {
  const input = readFileSync(`${DIR}/${f}`, 'utf8');
  let out, rc = 0;
  try {
    out = execFileSync(EXE, ['--a', input], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
  } catch (e) {
    rc = e.status ?? -1;
    out = (e.stderr || '').split('\n').filter((l) => /Error|error/.test(l)).slice(-1)[0] || '<no msg>';
  }
  if (rc === 0) ok++; else err++;
  if (process.env.VERBOSE) console.log(`${f} rc=${rc} in=${show(input)}\n     out=${show(out)}`);
}
console.log(`total=${files.length} rc0=${ok} rcNonZero=${err}`);
